import {T,step,v,n,o,p,f,pow,sub,prime,eq,plus,minus,x,y,C,fn,lines} from '../../../study/math.js';
const scored=steps=>steps.map(st=>({...st,label:T(st.label.tr+' (2 puan)',st.label.en+' (2 points)')}));
const A=v('A'),B=v('B'),res=lines(p(minus+n(13)+A+minus+n(9)+B+minus+n(6))+fn('sin',n(3)+x),plus+p(n(9)+A+minus+n(13)+B)+fn('cos',n(3)+x));
const singular=[
 step('1. Normal biçimin bölgesini söyle','1. State the normal-form domain',prime('y')+eq+f(n(2)+y,x),'x≠0 için yazılabilir. x=0’da bu biçimi kullanarak teoremi uygulayamazsın; asıl denklem hâlâ incelenebilir.','This form requires x≠0. The theorem cannot be applied through x=0 in this form; the original equation can still be examined.'),
 step('2. Orijinal denklemi sıfırda incele','2. Examine the original equation at zero',n(0)+o('·')+prime('y')+p(n(0))+eq+n(2)+y+p(n(0)),'Denklem y(0)=0 koşulunu zorunlu kılar. y(0)=1 verisi çelişkilidir; çözüm yoktur.','The equation forces y(0)=0. The datum y(0)=1 is inconsistent, so no solution exists.'),
 step('3. Tek bir çözüm bulmakla yetinme','3. Do not stop after finding one solution',y+eq+C+pow(x,n(2)),'Her C için türev 2Cx ve xy′=2Cx²=2y. Bütün bu eğriler başlangıç noktası (0,0)’dan geçer.','For every C, y′=2Cx and xy′=2Cx²=2y. All these curves pass through (0,0).'),
 step('4. Yerel teklik ile devamı ayır','4. Distinguish local uniqueness from continuation',C+eq+f(sub(y,n(0)),pow(sub(x,n(0)),n(2))),'x₀≠0 ise aynı yarı eksende katsayı sabitlenir. Diğer tarafa x=0 üzerinden geçerken ayrı katsayıyla C¹ devam mümkündür.','When x₀≠0 the coefficient is fixed on that half-axis. Across x=0, a separate coefficient permits different C¹ continuations.'),
 step('5. Teoremin verdiği sonucu doğru sınırla','5. Limit the theorem’s conclusion',lines(y+eq+v('a')+pow(x,n(2))+o(',')+x+o('≥')+n(0),y+eq+v('b')+pow(x,n(2))+o(',')+x+o('<')+n(0)),'“Teorem uygulanamıyor” bir sonucun kendisi değildir. Yokluk çelişkiyle, çokluk en az iki farklı çözümle kanıtlanır.','Failure of a theorem’s assumptions is not a conclusion by itself. Prove nonexistence by contradiction and nonuniqueness by distinct solutions.')
];
const verify=[
 step('1. Aday ailesini yaz','1. Write the candidate family',lines(y+eq+sub(C,n(1))+pow(v('e'),minus+n(4)+x)+plus+sub(C,n(2))+pow(v('e'),x),plus+A+fn('sin',n(3)+x)+plus+B+fn('cos',n(3)+x)),'C₁ ve C₂ serbest; A ve B ise zorlama terimini üretmek üzere belirlenecek.','C₁ and C₂ are free; A and B must be chosen to produce the forcing.'),
 step('2. Analitik türevleri hesapla','2. Compute analytic derivatives',lines(prime('y')+eq+minus+n(4)+sub(C,n(1))+pow(v('e'),minus+n(4)+x)+plus+sub(C,n(2))+pow(v('e'),x),plus+n(3)+A+fn('cos',n(3)+x)+minus+n(3)+B+fn('sin',n(3)+x)),'İkinci türevde üstel terimlerin katsayıları 16 ve 1, trigonometrik terimlerin katsayısı −9’dur.','In y′′ the exponential coefficients are 16 and 1; the trigonometric coefficients are −9.'),
 step('3. Artık fonksiyonunu kur','3. Form the residual',v('R')+eq+res,'R=y′′+3y′−4y−6sin3x. Homojen çözümün C₁ ve C₂ terimleri birbirini götürür.','R=y′′+3y′−4y−6sin3x. The C₁ and C₂ terms from the homogeneous solution cancel.'),
 step('4. İki katsayıyı birlikte sıfırla','4. Set both coefficients to zero',lines(minus+n(13)+A+minus+n(9)+B+eq+n(6),n(9)+A+minus+n(13)+B+eq+n(0)),'Sinüs ve kosinüs bir aralıkta doğrusal bağımsızdır; her iki katsayı da sıfır olmalı.','Sine and cosine are linearly independent on an interval, so both residual coefficients must vanish.'),
 step('5. Özdeşliği denetle','5. Check the identity',A+eq+minus+f(n(39),n(125))+o(',')+B+eq+minus+f(n(27),n(125)),'Bu değerlerle artık bütün aralıkta sıfırdır. Tek bir x için R(x)=0 görmek bunun yerine geçmez.','These values make the residual zero throughout the interval. R(x)=0 at one point is insufficient.')
];
